import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;
    casesUrl = '';

    connectedCallback() {
        const pageRef = {
            type: 'standard__page',
            attributes: {
                apiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        };
        this[NavigationMixin.GenerateURL](pageRef).then((url) => {
            this.casesUrl = url;
        });
    }

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'new-contact') {
            this.openNewContact();
        } else if (action === 'contacts') {
            this.openContacts();
        } else if (action === 'edit') {
            this.openEdit();
        }
    }

    openNewContact() {
        const pageRef = {
            type: 'standard__page',
            attributes: {
                apiName: 'Contact',
                actionName: 'new'
            },
            state: {
                defaultFieldValues: encodeDefaultFieldValues({
                    AccountId: this.recordId
                })
            }
        };
        this[NavigationMixin.Navigate](pageRef);
    }

    openContacts() {
        const pageRef = {
            type: 'standard__page',
            attributes: {
                apiName: 'Account',
                actionName: 'view'
            },
            state: {
                recordIds: this.recordId,
                relCtx: 'Contacts'
            }
        };
        this[NavigationMixin.Navigate](pageRef);
    }

    openEdit() {
        const pageRef = {
            type: 'standard__recordPage',
            attributes: {
                apiName: 'Account',
                actionName: 'edit',
                recordId: this.recordId
            }
        };
        this[NavigationMixin.Navigate](pageRef);
    }
}
