import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE,
    MessageContext
} from 'lightning/messageService';
import Account_Selected from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedAccountId = null;
    _registration;

    @wire(MessageContext)
    wireMessageContext(context) {
        this._messageContext = context;
        this._registerChannel();
    }

    disconnectedCallback() {
        if (this._registration) {
            unsubscribe(this._registration);
            this._registration = undefined;
        }
    }

    _registerChannel() {
        if (this._registration) {
            return; // already subscribed – never hold more than one subscription
        }
        if (this._messageContext) {
            this._registration = subscribe(
                this._messageContext,
                Account_Selected,
                (message) => this.handleAccountSelected(message),
                APPLICATION_SCOPE
            );
        }
    }

    handleAccountSelected(message) {
        this.selectedAccountId = message.recordId || null;
    }

    handleClear(event) {
        if (event.target.dataset.action === 'clear') {
            publish(this._messageContext, Account_Selected, { recordId: null });
        }
    }
}
