import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasData;

    _intervalId = null;
    _isRequestInFlight = false;
    _visibilityHandler = null;

    connectedCallback() {
        this._visibilityHandler = this._onVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._visibilityHandler);

        this._loadStats();

        this._intervalId = setInterval(() => {
            this._loadStats();
        }, 60000);
    }

    disconnectedCallback() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
        this._isRequestInFlight = false;
    }

    _onVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this._loadStats();
        }
    }

    _loadStats() {
        if (document.visibilityState === 'hidden') {
            return;
        }
        if (this._isRequestInFlight) {
            return;
        }

        this._isRequestInFlight = true;

        getQueueStats()
            .then((result) => {
                this._isRequestInFlight = false;
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasData = true;
                this.errorMessage = null;
            })
            .catch((error) => {
                this._isRequestInFlight = false;
                this.errorMessage = error.body.message;
            });
    }
}
