import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];

    @api
    get options() {
        return this._options;
    }

    set options(newValue) {
        this._options = newValue || [];
        this._updateActiveFromValue();
    }

    _value = '';
    _activeIndex = 0;

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue || '';
        this._updateActiveFromValue();
    }

    get displayOptions() {
        return this._options.map((opt, idx) => ({
            id: `status-option-${idx}`,
            value: opt.value,
            label: opt.label,
            selected: opt.value === this._value
        }));
    }

    get activeId() {
        if (this._options.length === 0) {
            return undefined;
        }
        return `status-option-${this._activeIndex}`;
    }

    _updateActiveFromValue() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(opt => opt.value === this._value);
        this._activeIndex = index >= 0 ? index : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectOption(this._activeIndex);
                break;
        }
    }

    handleClick(event) {
        const li = event.target.closest('li[role="option"]');
        if (!li) {
            return;
        }
        const value = li.dataset.value;
        const index = this._options.findIndex(opt => opt.value === value);
        if (index >= 0) {
            this._selectOption(index);
        }
    }

    _selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }

        if (option.value === this._value) {
            return;
        }

        this._value = option.value;
        this._activeIndex = index;

        this.dispatchEvent(new CustomEvent('change', {
            detail: { value: option.value }
        }));
    }
}
